+using Uinsure.Policies.Domain.Rules;
+
 namespace Uinsure.Policies.Domain.Common;

 public sealed class Result<T>
 {
-    public bool IsSuccess { get; }
-    public required T Value { get; init; }
-    public required IReadOnlyList<RuleViolation> Violations { get; init; }
-    public static Result<T> Success(T value) => throw new NotImplementedException();
-    public static Result<T> Failure(params RuleViolation[] violations) => throw new NotImplementedException();
+    private readonly T? _value;
+
+    private Result(T? value, IReadOnlyList<RuleViolation> violations)
+    {
+        _value = value;
+        Violations = violations;
+    }
+
+    public bool IsSuccess => Violations.Count == 0;
+
+    public T Value => IsSuccess
+        ? _value!
+        : throw new InvalidOperationException("A failed result has no value.");
+
+    public IReadOnlyList<RuleViolation> Violations { get; }
+
+    public static Result<T> Success(T value) => new(value, []);
+
+    public static Result<T> Failure(params RuleViolation[] violations)
+    {
+        if (violations.Length == 0)
+        {
+            throw new ArgumentException("A failure needs at least one violation.", nameof(violations));
+        }
+
+        var order = RuleIds.Order.ToList();
+        var ordered = violations.OrderBy(violation => order.IndexOf(violation.RuleId)).ToArray();
+        return new Result<T>(default, ordered);
+    }
 }
diff --git a/src/Uinsure.Policies.Domain/Policies/Policy.cs b/src/Uinsure.Policies.Domain/Policies/Policy.cs
index 4558ff2..226982d 100644
--- a/src/Uinsure.Policies.Domain/Policies/Policy.cs
+++ b/src/Uinsure.Policies.Domain/Policies/Policy.cs
@@ -1,10 +1,102 @@
 using Uinsure.Policies.Domain.Common;
+using Uinsure.Policies.Domain.Rules;

 namespace Uinsure.Policies.Domain.Policies;

 public sealed class Policy
 {
-    public required IReadOnlyList<Policyholder> Policyholders { get; init; }
-    public required IReadOnlyList<Term> Terms { get; init; }
-    public static Result<Policy> Sell(PolicyReference reference, PolicyType type, DateOnly start, decimal amount, bool autoRenew, IReadOnlyList<Policyholder> holders, Property property, PaymentMethod method, string paymentReference, DateOnly today) => throw new NotImplementedException();
+    private const int MaxDaysAhead = 60;
+    private const int MaxPolicyholders = 3;
+    private const int MinimumAge = 16;
+
+    private Policy(
+        PolicyReference reference,
+        PolicyType type,
+        bool autoRenew,
+        IReadOnlyList<Policyholder> policyholders,
+        Property property,
+        Term term)
+    {
+        Reference = reference;
+        Type = type;
+        AutoRenew = autoRenew;
+        Policyholders = policyholders;
+        Property = property;
+        Terms = [term];
+        Version = Guid.NewGuid();
+    }
+
+    public PolicyReference Reference { get; }
+    public PolicyType Type { get; }
+    public bool AutoRenew { get; }
+    public bool HasClaims { get; }
+    public Guid Version { get; }
+    public IReadOnlyList<Policyholder> Policyholders { get; }
+    public Property Property { get; }
+    public IReadOnlyList<Term> Terms { get; }
+
+    // SELL-2, 4, 5 and 7 are all checked; none returns early.
+    public static Result<Policy> Sell(
+        PolicyReference reference,
+        PolicyType type,
+        DateOnly start,
+        decimal amount,
+        bool autoRenew,
+        IReadOnlyList<Policyholder> holders,
+        Property property,
+        PaymentMethod method,
+        string paymentReference,
+        DateOnly today)
+    {
+        var violations = new List<RuleViolation>();
+
+        var earliest = today;
+        var latest = today.AddDays(MaxDaysAhead);
+        if (start < earliest || start > latest)
+        {
+            violations.Add(Violation(
+                RuleIds.Sell2,
+                $"The start date must be between {earliest:yyyy-MM-dd} and {latest:yyyy-MM-dd}.",
+                ("earliest", earliest),
+                ("latest", latest)));
+        }
+
+        if (holders.Count is < 1 or > MaxPolicyholders)
+        {
+            violations.Add(Violation(
+                RuleIds.Sell4,
+                $"A policy needs 1 to {MaxPolicyholders} policyholders.",
+                ("count", holders.Count)));
+        }
+
+        for (var i = 0; i < holders.Count; i++)
+        {
+            // SELL-5: 16 or older on the start date, so the 16th birthday itself passes.
+            if (holders[i].DateOfBirth.AddYears(MinimumAge) > start)
+            {
+                violations.Add(Violation(
+                    RuleIds.Sell5,
+                    $"Policyholder {i + 1} must be {MinimumAge} or older on the start date.",
+                    ("index", i + 1)));
+            }
+        }
+
+        if (amount <= 0)
+        {
+            violations.Add(Violation(RuleIds.Sell7, "The policy amount must be greater than 0.", ("amount", amount)));
+        }
+
+        if (violations.Count > 0)
+        {
+            return Result<Policy>.Failure([.. violations]);
+        }
+
+        // SELL-6: the payment is for the full amount, by the method sold with.
+        var payment = new Payment(paymentReference, method, amount);
+        var term = new Term(start, amount, payment);
+        return Result<Policy>.Success(new Policy(reference, type, autoRenew, holders, property, term));
+    }
+
+    private static RuleViolation Violation(string ruleId, string message, params (string Key, object? Value)[] extensions) =>
+        new(ruleId, ViolationKind.BusinessRule, message, extensions.ToDictionary(e => e.Key, e => e.Value));
 }
